  ('SR', 'School Refusal', '厌学', 'EQAI厌学自评量表', '身心健康', 1, true, 2),
  ('ER_Aware', '(Negative) Emotional Regulation - Emotional Awareness and Understanding', '(负面)情绪管理 - 情绪的觉察与理解', 'EQAI负面情绪管理量表', '能力与发展', 2, true, 3),
  ('ER_Accept', '(Negative) Emotional Regulation - Emotion Acceptance', '(负面)情绪管理 - 情绪接纳', 'EQAI负面情绪管理量表', '能力与发展', 2, true, 4),
  ('ER_ImpulseControl', '(Negative) Emotional Regulation - Impulse Control', '(负面)情绪管理 - 冲动控制', 'EQAI负面情绪管理量表', '能力与发展', 2, true, 5),
