  ('Soc_Stress', 'Social Stress', '人际关系压力', 'EQAI人际关系压力量表', '身心健康', 1, true, 10),
  ('SSD', 'Somatic Symptom Disorder', '躯体性问题', 'EQAI躯体化症状量表', '身心健康', 1, true, 11),
  ('Aca_Competence', 'Academic Competence', '学业能力', 'EQAI学业能力量表', '能力与发展', 2, true, 12),
  ('ADHD_Inattention', 'Attention-Deficit/Hyperactivity Disorder - Inattention', '注意力缺陷多动障碍 - 注意缺陷', 'EQAI注意力缺陷多动障碍筛查量表', '身心健康', 1, true, 13),
  ('ADHD_Hyperact', 'Attention-Deficit/Hyperactivity Disorder - Hyperactivity/Impulsivity', '注意力缺陷多动障碍 - 冲动/多动', 'EQAI注意力缺陷多动障碍筛查量表', '身心健康', 1, true, 14),
  ('ADHD _Oppose', 'Attention-Deficit/Hyperactivity Disorder - Opposition/Conflict', '注意力缺陷多动障碍 - 违抗/冲突', 'EQAI注意力缺陷多动障碍筛查量表', '身心健康', 1, true, 15),
  ('ADHD_EmoReg', 'Attention-Deficit/Hyperactivity Disorder - EmoRegulation', '注意力缺陷多动障碍 - 情绪调节困难', 'EQAI注意力缺陷多动障碍筛查量表', '身心健康', 1, true, 16),
  ('ADHD_Motiv', 'Attention-Deficit/Hyperactivity Disorder - Delay Aversion', '注意力缺陷多动障碍 - 动机/延迟满足', 'EQAI注意力缺陷多动障碍筛查量表', '身心健康', 1, true, 17),
  ('16PF', 'Cattell''s 16 Personality Factors Test', '卡特尔十六种人格因素测验', 'EQAI人格因素测验', '能力与发展', 2, true, 18),
  ('Achenbach_YSR', 'Achenbach System - Youth Self-Report', '青少年自评量表', 'EQAI身心健康自评筛查', '身心健康', 1, true, 19),
  ('Achenbach_CBCL', 'Achenbach System - Child Behavior Checklist', '儿童青少年行为量表', 'EQAI身心健康他评筛查（家长）', '家长参与', 3, true, 20)
